export function getSafariBySlug(slug: string): Safari | undefined {
    return safaris.find(safari => safari.slug === slug);
}

export function getSafarisByDestination(destination: Safari['destination']): Safari[] {
    return safaris.filter(safari => safari.destination === destination);
}

export function getFeaturedSafaris(): Safari[] {
    return safaris.filter(safari => safari.featured);
}

export function getSafarisByType(type: string): Safari[] {
    return safaris.filter(safari => safari.type?.includes(type));
}
